import Foundation

/// Real WHOOP 4.0 wrist accelerometer recordings (one strap, one wearer, 2026-10-03), from the realtime
/// type-43 stream. Stored at 25 Hz (each value the mean of four consecutive 100 Hz samples) to keep the
/// source small; gait lines sit below 4 Hz, so nothing the detector reads is lost. Layout: little-endian
/// Int16, interleaved x, y, z, in raw units of 1/4096 g. Acceleration only, no identifiers.
enum GaitFixtures {
    static let sampleRate = 25.0

    static func axes(_ base64: String) -> (x: [Double], y: [Double], z: [Double]) {
        let data = Data(base64Encoded: base64)!
        var x: [Double] = [], y: [Double] = [], z: [Double] = []
        data.withUnsafeBytes { raw in
            for i in stride(from: 0, to: raw.count - 5, by: 6) {
                func value(_ offset: Int) -> Double {
                    Double(Int16(bitPattern: UInt16(raw[i + offset]) | UInt16(raw[i + offset + 1]) << 8)) / 4096
                }
                x.append(value(0)); y.append(value(2)); z.append(value(4))
            }
        }
        return (x, y, z)
    }

